node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Find mouse products
const products = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Mouse%'\").all();
console.log('=== MOUSE PRODUCTS FOUND ===');
for (const p of products) {
    console.log('Product:', p.name, '| ID:', p.product_id);
    const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(p.product_id);
    console.log('  Variants (' + variants.length + '):');
    for (const v of variants) {
        const opts = JSON.parse(v.options || '{}');
        console.log('    Item ID:', v.item_id, '| Price: \$' + v.price, '| Available:', !!v.available, '| Options:', JSON.stringify(opts));
    }
    console.log();
}

// Check table schema
console.log('=== PRODUCTS TABLE COLUMNS ===');
const cols = db.prepare(\"PRAGMA table_info('products')\").all();
console.log(cols.map(c => c.name).join(', '));

console.log('=== RT_VARIANTS TABLE COLUMNS ===');
const vcols = db.prepare(\"PRAGMA table_info('rt_variants')\").all();
console.log(vcols.map(c => c.name).join(', '));

db.close();
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get full details for the LogiTech Wireless Mouse M310
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-FA0948'\").get();
console.log('=== FULL PRODUCT DETAILS ===');
for (const [key, value] of Object.entries(product)) {
    console.log(key + ':', value);
}

// Also check rt_variants more broadly
console.log('\n=== ALL VARIANTS FOR THIS PRODUCT ===');
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-FA0948'\").all();
console.log('Count:', variants.length);
for (const v of variants) console.log(v);

// Check if variants are stored in the products table itself
console.log('\n=== VARIANTS_JSON ===');
console.log(product.variants_json);

console.log('\n=== SPECS_JSON ===');
console.log(product.specs_json);

console.log('\n=== COMPATIBLE_WITH_JSON ===');
console.log(product.compatible_with_json);

db.close();
"

