const db = require('better-sqlite3')('/workspace/world.db');

// Look up compatible products
const compatIds = ['PROD-B98D14','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
console.log('=== COMPATIBLE PRODUCTS ===');
for (const id of compatIds) {
    const p = db.prepare('SELECT product_id, name, category, brand, price FROM products WHERE product_id = ?').get(id);
    if (p) console.log(p.product_id + ':', p.name, '| Brand:', p.brand, '| Price: \$' + p.price);
}

db.close();
"
